    html += anCard('Music heard by ' + g, anChart(labels, [{ name: 'Hours heard', values: per.map(function (p) { return p.h / 3600; }), color: COL[0] }], [], { fmt: hfmt }), 'Seconds the music was playing and audible, while the page was in view.');
    html += anCard('Music heard as a share of play time', anChart(labels, [], [{ name: 'Heard ÷ played', values: per.map(function (p) { return p.t && p.h ? Math.min(100, p.h / p.t * 100) : null; }), color: COL[1] }], { pct: true, fmt: function (v) { return anPct(v); } }), 'Days with no music reported are left out. Play time from games that don’t report music yet still counts below the line, so early on this reads low.');
    var times = [['Heard', M.heard, COL[2]], ['Paused by the player', M.paused, COL[3]], ['Playing but muted', M.muted, COL[5]]];
    html += anCard('Playing vs paused vs muted', anHbars(times.map(function (t) { return { label: t[0], share: muTime ? t[1] / muTime * 100 : 0, value: hrs(t[1]) + ' · ' + anPct(muTime ? t[1] / muTime * 100 : null), color: t[2] }; })), 'Time since the music began on each page load, with the page in view.');
