  const was = had?.stats ?? null;
  for (const [tpl, row] of Object.entries(st?.m ?? {})) {
    if (!Array.isArray(row)) continue;
    const before = was?.m?.[tpl] ?? [];
    const d = grew(n(row[4]), n(before[4])), x = grew(n(row[2]), n(before[2]));
    if (d) t.done[tpl] = (t.done[tpl] ?? 0) + d;
    if (x) t.declined[tpl] = (t.declined[tpl] ?? 0) + x;
  }
  for (const q of Array.isArray(m.missions) ? m.missions : []) if (typeof q?.tpl === "string" && typeof q.title === "string" && Object.keys(t.titles).length < 600) t.titles[q.tpl] = q.title.slice(0, 60);
  const since = n(had?.played);
  for (const o of Array.isArray(st?.own) ? st.own : []) if (had && typeof o?.m === "string" && n(o.b) > since) t.bought[o.m] = (t.bought[o.m] ?? 0) + 1;
  const g = n(m.hq?.grade), g0 = n(had?.hq?.grade);
