var REGION_SHAPES_A = {
  // ---- the Sands ----
  // the ranges of rooms round the court; the gate and the court itself are open
  caravanserai: (W2) => {
    const o = W2 / 2 - 0.12, T = 0.36;
    return (x, z) => Math.max(Math.abs(x), Math.abs(z)) <= o && Math.max(Math.abs(x), Math.abs(z)) >= o - T && !(z > 0 && Math.abs(x) < 0.25);
  },
  windTower: () => boxes({ x: 0.08, z: 0.1, w: 0.7, d: 0.6 }, { x: -0.16, z: -0.22, w: 0.3, d: 0.3 }),
  // the walls, towers and keep; the court between them is open through the gate
  kasbah: (W2) => {
    const o = W2 / 2 - 0.2;
    return (x, z) => boxes({ x: 0, z: -0.35, w: 1.3, d: 0.9 })(x, z) || Math.max(Math.abs(x), Math.abs(z)) <= o + 0.26 && Math.max(Math.abs(x), Math.abs(z)) >= o - 0.26 && !(z > 0 && Math.abs(x) < 0.25);
  },
  // the great pyramid, the two lesser, the sphinx and the pylons; the avenue and forecourt are open
  pyramid: (_W, D) => boxes(
    { x: 0, z: -8, w: 10, d: 10 },
    { x: -7.4, z: -10.5, w: 4.2, d: 4.2 },
    { x: 7.5, z: -6.5, w: 3.8, d: 3.8 },
    { x: -4.3, z: 2.6, w: 1.7, d: 3.8 },
    { x: -1.85, z: D / 2 - 1.2, w: 1.7, d: 0.9 },
    { x: 1.85, z: D / 2 - 1.2, w: 1.7, d: 0.9 }
  ),
  // ---- the Icefield ----
  researchStation: () => (x, z) => Math.hypot(x + 0.7, z + 0.55) <= 0.55 || Math.hypot(x - 0.55, z + 0.7) <= 0.47 || Math.hypot(x - 0.7, z - 0.45) <= 0.42,
  sledKennels: (W2, D) => boxes({ x: 0, z: -D / 2 + 0.35, w: W2 - 0.3, d: 0.46 }),
  // the domed hall, the wings and the tunnel; the lake, the sculpture ring and the path are open
  iceHotel: () => (x, z) => Math.hypot(x, z + 0.2) <= 1.45 || boxes({ x: 0, z: -0.2, w: 10.3, d: 1.4 }, { x: -4.55, z: -0.2, w: 1.2, d: 3.4 }, { x: 4.55, z: -0.2, w: 1.2, d: 3.4 }, { x: 0, z: 1.6, w: 1, d: 1.9 })(x, z),
  // ---- the Shallows ----
  beachClub: (W2, D) => boxes({ x: -W2 / 2 + 0.55, z: -D / 2 + 0.5, w: 0.8, d: 0.66 }),
  resortVillas: () => boxes(...VILLAS.map(([x, z, w, d]) => ({ x, z, w, d }))),
  // the pavilion, the wheel's base, the helter-skelter and the kiosks; the deck between is drivable
  pleasurePier: (W2, D) => (x, z) => Math.hypot(x + 1.3, z - 4.6) <= 0.5 || boxes({ x: 0, z: D / 2 - 1.95, w: W2 - 0.2, d: 3.3 }, { x: 1.2, z: -1.2, w: 0.9, d: 2 })(x, z) || [0, 1, 2].some((i) => boxes({ x: -W2 / 2 + 0.41, z: -D / 2 + 2.4 + i * 2.2, w: 0.48, d: 0.48 })(x, z))
};

