  // the market hall under the guildhall is open to walk through, but not to drive: the whole block
  guildhall: (W2, D) => boxes4({ x: 0, z: -0.1, w: W2 - 0.3, d: D - 0.45 }),
  titheBarn: (W2, D) => boxes4({ x: 0, z: -0.1, w: W2 - 0.2, d: D - 0.45 }, { x: 0, z: D / 2 - 0.5, w: 0.66, d: 0.5 }),
