  villageHall: (W2, D) => boxes5({ x: 0, z: -0.14, w: W2 - 0.34, d: D - 0.5 }),
  communityCentre: (W2, D) => boxes5({ x: 0, z: -D / 2 + 0.1 + D * 0.275, w: W2 - 0.3, d: D * 0.55 }),
  kindergarten: (W2, D) => boxes5({ x: 0, z: -D / 2 + 0.4, w: W2 - 0.3, d: 0.6 }, { x: -W2 / 2 + 0.45, z: 0, w: 0.6, d: D - 0.6 }),
