// src/game/nearRoad.ts
function nearestRoad2(w, x, z, r) {
  let best = -1, bestD = Infinity;
  const cx = Math.floor(x), cz = Math.floor(z);
  for (let tz = cz - r; tz <= cz + r; tz++) {
    for (let tx = cx - r; tx <= cx + r; tx++) {
      if (!inB(tx, tz)) continue;
      const i = idx(tx, tz);
      if (!(w.road[i] > 0) || w.blocked[i]) continue;
      const d = Math.hypot(tx + 0.5 - x, tz + 0.5 - z);
      if (d < bestD) {
        bestD = d;
        best = i;
      }
    }
  }
  return best;
}

